+// kms_region_allowed checks that the requested KMS key is located in an allowed region
+func kmsRegionAllowed(ctx context.Context, attrs Attributes) (bool, error) {
+    keyARN := attrs.Resource.Get("key_arn")
+    keyMeta, err := keymanager.GetKeyMetadata(ctx, keyARN)
+    if err != nil {
+        return false, err
+    }
+    return residencyPolicyEvaluator(attrs.Principal, keyMeta.Region), nil
+}
